mapper.sql:
WHERE g.deleted_at IS NULL AND sg.status IN ('01', '02')
AND (g.group_name LIKE #{keywordPattern} ESCAPE '!' OR g.description LIKE #{keywordPattern} ESCAPE '!')
AND r.region_name = #{regionName}

mapper.select:
SELECT region_id
FROM region
WHERE region_name = #{regionName}

SELECT EXISTS(
SELECT 1 FROM members
WHERE member_id = #{memberId}
AND deleted_at IS NULL
)

mapper.sql:
FROM meeting_approval ma JOIN `groups` g ON g.group_id = ma.group_id JOIN saving_group sg ON sg.group_id = g.group_id JOIN members m ON m.member_id = g.member_id JOIN region r ON r.region_id = g.region_id WHERE ma.type = 'CREATE' AND g.deleted_at IS NULL AND m.deleted_at IS NULL
AND ma.status = #{status}
AND g.group_name LIKE #{keywordPattern} ESCAPE '!'

mapper.update:
UPDATE group_member
SET membership_status = 'EXPELLED'
WHERE crew_member_id = #{crewMemberId}
AND group_id = #{groupId}
AND membership_status = 'APPROVED'

UPDATE group_member
SET membership_status = 'LEFT',
left_at = CURRENT_TIMESTAMP
WHERE crew_member_id = #{crewMemberId}
AND group_id = #{groupId}
AND membership_status = 'APPROVED'

UPDATE saving_group sg
JOIN `groups` g ON g.group_id = sg.group_id
SET sg.status = #{status}
WHERE sg.group_id = #{groupId}
AND g.deleted_at IS NULL

mapper.sql:
SELECT crew_member_id, member_id, group_id, membership_status
FROM group_member
WHERE crew_member_id = #{crewMemberId}

mapper.update:
UPDATE group_member
SET membership_status = 'APPROVED',
member_role = 'MEMBER',
joined_at = CURRENT_TIMESTAMP,
approved_at = CURRENT_TIMESTAMP,
approved_by = #{approvedBy}
WHERE crew_member_id = #{crewMemberId}
AND group_id = #{groupId}
AND membership_status = 'PENDING'

mapper.select:
SELECT group_id, COUNT(DISTINCT member_id) AS member_count FROM group_member WHERE membership_status = 'APPROVED' AND group_id IN
#{groupId}
GROUP BY group_id

SELECT notice_id, title FROM group_notice
WHERE group_id = #{groupId}
ORDER BY created_at DESC, notice_id DESC LIMIT 4

SELECT DISTINCT member_role FROM group_member
WHERE group_id = #{groupId} AND member_id = #{memberId}
AND membership_status = 'APPROVED'
